#!/usr/bin/env python3
"""Complete capture-first C/P shared-procedure/process ownership selection."""
import json,re
from pathlib import Path
BASE=Path(__file__).resolve().parent
controls=[]
def proc(name='First',params='a=0',locals='',body='F:x:=x+a; R:return;'):
    return dict(name=name,params=params,locals=locals,body=body)
def process(name,domain,binding='=',locals='',body=None,fair=''):
    return dict(name=name,domain=domain,binding=binding,locals=locals,body=body or ('L:call First(1); E:skip;' if name=='One' else 'M:call First(2); N:skip;'),fair=fair)
def case(name,processes=None,procedures=None,globals='variable x=0;',options=None,fair=False):
    controls.append(dict(name=name,processes=processes or [process('One','1'),process('Two','2')],procedures=procedures or [proc()],globals=globals,options=options or [],fair=fair))
case('two_constants')
case('constants_reverse',processes=[process('One','2'),process('Two','1')])
case('two_string_constants',processes=[process('One','"z"'),process('Two','"a"')])
case('member_before_constant',processes=[process('One','{2,3}','\\in'),process('Two','1')])
case('constant_before_member',processes=[process('One','1'),process('Two','{2,3}','\\in')])
case('two_members',processes=[process('One','{1,2}','\\in'),process('Two','{3,4}','\\in')])
case('two_member_strings',processes=[process('One','{"z","b"}','\\in'),process('Two','{"a","c"}','\\in')])
case('two_intervals',processes=[process('One','1..2','\\in'),process('Two','3..4','\\in')])
case('empty_member',processes=[process('One','{}','\\in'),process('Two','2')])
case('reverse_interval',processes=[process('One','2..1','\\in'),process('Two','2')])
case('two_empty',processes=[process('One','{}','\\in'),process('Two','2..1','\\in')])
case('duplicate_member_elements',processes=[process('One','{1,1}','\\in'),process('Two','2')])
case('three_constants',processes=[process('One','1'),process('Two','2'),process('Three','3',body='O:call First(3); P:skip;')])
case('three_interleaved',processes=[process('One','{3}','\\in'),process('Two','2'),process('Three','{1}','\\in',body='O:call First(self); P:skip;')])
case('constant_locals',processes=[process('One','1',locals='variable y=1;',body='L:call First(y); E:y:=x;'),process('Two','2',locals='variable z=2;',body='M:call First(z); N:z:=x;')])
case('member_locals',processes=[process('One','{1}','\\in',locals='variable y=self;',body='L:call First(y); E:y:=x;'),process('Two','{2}','\\in',locals='variable z=self;',body='M:call First(z); N:z:=x;')])
case('mixed_locals',processes=[process('One','{1}','\\in',locals='variable y=self;',body='L:call First(y); E:y:=x;'),process('Two','2',locals='variable z=2;',body='M:call First(z); N:z:=x;')])
case('earlier_process_locals',processes=[process('One','1',locals='variable y=1,q=y+1;'),process('Two','{2}','\\in',locals='variable z=self,t=z+1;')])
case('membership_locals',processes=[process('One','1',locals='variable y \\in {1,2};'),process('Two','{2}','\\in',locals='variable z \\in {1,2};')])
case('default_process_locals',processes=[process('One','1',locals='variable y;'),process('Two','2',locals='variable z;')])
case('parameter_earlier',procedures=[proc(params='a=0,b=a+1',body='F:x:=x+a+b; R:return;')],processes=[process('One','1',body='L:call First(1,2); E:skip;'),process('Two','2',body='M:call First(2,3); N:skip;')])
case('local_earlier',procedures=[proc(locals='variable u=a+1,v=u+1;',body='F:x:=x+u+v; R:return;')])
case('local_self',procedures=[proc(locals='variable u=self;',body='F:x:=x+u; R:return;')])
case('process_self',processes=[process('One','{1}','\\in',body='L:call First(self); E:skip;'),process('Two','{2}','\\in',body='M:call First(self); N:skip;')])
case('constant_self',processes=[process('One','1',body='L:call First(self); E:skip;'),process('Two','2')])
case('procedure_self',procedures=[proc(body='F:x:=x+self; R:return;')])
case('repeat_calls',processes=[process('One','1',body='L:call First(1); E:call First(2); Z:skip;'),process('Two','2')])
case('self_recursive',procedures=[proc(body='F:if a>0 then call First(a-1); else x:=x+1; end if; R:return;')])
case('recursive_locals',procedures=[proc(locals='variable u=a;',body='F:if a>0 then call First(a-1); else x:=x+u; end if; R:x:=x+u; return;')])
case('self_tail',procedures=[proc(body='F:if a>0 then call First(a-1); return; else x:=x+1; end if; R:return;')])
case('tail_locals',procedures=[proc(locals='variable u=a+1,v=u+1;',body='F:if a>0 then call First(a-1); return; else x:=x+u+v; end if; R:return;')])
case('tail_parallel_arguments',procedures=[proc(params='a=0,b=1',body='F:if a>0 then call First(a-1,a); return; else x:=x+b; end if; R:return;')],processes=[process('One','1',body='L:call First(1,3); E:skip;'),process('Two','2',body='M:call First(2,4); N:skip;')])
case('two_procedures',procedures=[proc(),proc('Second','b=0',body='S:x:=x+b; T:return;')],processes=[process('One','1'),process('Two','2',body='M:call Second(2); N:skip;')])
case('nested_calls',procedures=[proc(body='F:call Second(a); R:x:=x+a; return;'),proc('Second','b=0',body='S:x:=x+b; T:return;')])
case('cross_tail',procedures=[proc(body='F:call Second(a); return;'),proc('Second','b=0',body='S:x:=x+b; T:return;')])
case('mutual',procedures=[proc(body='F:if a>0 then call Second(a-1); else x:=x+1; end if; R:return;'),proc('Second','b=0',body='S:if b>0 then call First(b-1); else x:=x+1; end if; T:return;')])
case('mutual_tail',procedures=[proc(body='F:if a>0 then call Second(a-1); return; else x:=x+1; end if; R:return;'),proc('Second','b=0',body='S:if b>0 then call First(b-1); return; else x:=x+1; end if; T:return;')])
case('missing_return',procedures=[proc(body='F:x:=x+a;')])
case('no_parameters',procedures=[proc(params='',body='F:x:=x+1; R:return;')],processes=[process('One','1',body='L:call First(); E:skip;'),process('Two','2',body='M:call First(); N:skip;')])
case('no_parameter_tail',procedures=[proc(params='',body='F:call First(); return;')],processes=[process('One','1',body='L:call First(); E:skip;'),process('Two','2',body='M:call First(); N:skip;')])
case('unused_procedure',procedures=[proc(),proc('Second','b=0',body='S:x:=x+b; T:return;')])
case('stack_whole',procedures=[proc(body='F:x:=Len(stack); R:return;')])
case('stack_owner',procedures=[proc(body='F:x:=x+Len(stack[self]); R:return;')])
case('pc_whole',procedures=[proc(body='F:x:=IF pc=pc THEN x+1 ELSE x; R:return;')])
case('pc_owner',procedures=[proc(body='F:x:=IF pc[self]=pc[self] THEN x+1 ELSE x; R:return;')])
case('infinite_call_loop',processes=[process('One','1',body='L:while TRUE do call First(1); end while;'),process('Two','2')])
case('global_fair',fair=True)
case('weak_process',processes=[process('One','1',fair='fair '),process('Two','2')])
case('strong_process',processes=[process('One','1'),process('Two','2',fair='fair + ')])
for option in ['-wf','-sf','-nof','-wfNext','-termination']:case('option_'+option[1:],options=[option])
case('procedure_modifier',procedures=[proc(body='F+:x:=x+a; R:return;')])
case('process_modifier',processes=[process('One','1',body='L+:call First(1); E:skip;'),process('Two','2')])
case('overlap_constants',processes=[process('One','1'),process('Two','1')])
case('overlap_members',processes=[process('One','{1,2}','\\in'),process('Two','{2,3}','\\in')])
case('overlap_interval',processes=[process('One','1..3','\\in'),process('Two','3')])
case('unproved_domain',processes=[process('One','Nat','\\in'),process('Two','2')])
case('escaped_string_id',processes=[process('One','"\\\\p"'),process('Two','2')])
case('cross_local_read',processes=[process('One','1',locals='variable y=1;'),process('Two','2',body='M:call First(y); N:skip;')])
case('procedure_local_read',processes=[process('One','1',locals='variable y=1;'),process('Two','2')],procedures=[proc(body='F:x:=x+y; R:return;')])
case('procedure_local_write',processes=[process('One','1',locals='variable y=1;'),process('Two','2')],procedures=[proc(body='F:y:=a; R:return;')])
case('duplicate_process_local',processes=[process('One','1',locals='variable y=1;'),process('Two','2',locals='variable y=2;')])
case('process_parameter_alias',processes=[process('One','1',locals='variable a=1;'),process('Two','2')])
case('procedure_process_alias',procedures=[proc(params='One=0',body='F:x:=One; R:return;')])
case('duplicate_process_name',processes=[process('One','1'),process('One','2',body='M:call First(2); N:skip;')])
case('label_alias',processes=[process('One','1'),process('Two','2',body='L:call First(2); N:skip;')])
case('procedure_process_name',procedures=[proc('One')],processes=[process('One','1',body='L:call One(1); E:skip;'),process('Two','2',body='M:call One(2); N:skip;')])
case('generated_procset_parameter',procedures=[proc(params='ProcSet=0',body='F:x:=ProcSet; R:return;')])
case('global_parameter_alias',procedures=[proc(params='x=0')])
case('unknown_call',processes=[process('One','1',body='L:call Missing(1); E:skip;'),process('Two','2')])
case('wrong_arity',processes=[process('One','1',body='L:call First(); E:skip;'),process('Two','2')])
case('cross_process_goto',processes=[process('One','1',body='L:call First(1); E:goto M;'),process('Two','2')])
case('procedure_process_goto',procedures=[proc(body='F:goto L;')])
case('undefined_argument',processes=[process('One','1',body='L:call First(Missing); E:skip;'),process('Two','2')])
case('unbounded_recursion',procedures=[proc(body='F:call First(a+1); R:return;')])
case('parameter_member',procedures=[proc(params='a \\in {1,2}')])
case('local_member',procedures=[proc(locals='variable u \\in {1,2};',body='F:x:=u; R:return;')])
case('default_parameter',procedures=[proc(params='a')])
case('default_local',procedures=[proc(locals='variable u;',body='F:x:=a; R:return;')])
case('empty_process_body',processes=[process('One','1',body=' '),process('Two','2')])
def cbody(text):
    return re.sub(r'\bwhile (.*?) do',lambda m:'while('+m[1]+'){',re.sub(r'\bif (.*?) then',lambda m:'if('+m[1]+'){',text)).replace('else','}else{').replace('end if;','};').replace('end while;','};')
rows=[];out=BASE/'cases';out.mkdir(exist_ok=True)
for syntax in ['C','P']:
 for control in controls:
    name='MultipleProcedure_'+syntax+'_'+control['name'];parts=['--'+('fair ' if control['fair'] else '')+'algorithm A'+(' {' if syntax=='C' else ''),control['globals']]
    for p in control['procedures']:
        parts.append(f"procedure {p['name']}({p['params']})\n{p['locals']}\n"+('{ '+cbody(p['body'])+' };' if syntax=='C' else 'begin\n'+p['body']+'\nend procedure;'))
    for p in control['processes']:
        header=p['fair']+'process '+(f"({p['name']} {p['binding']} {p['domain']})" if syntax=='C' else f"{p['name']} {p['binding']} {p['domain']}")
        parts.append(header+'\n'+p['locals']+'\n'+('{ '+cbody(p['body'])+' }' if syntax=='C' else 'begin\n'+p['body']+'\nend process;'))
    parts.append('}' if syntax=='C' else 'end algorithm;')
    source=f'---- MODULE {name} ----\nEXTENDS Integers, Sequences, TLC\n(* '+ '\n'.join(parts)+' *)\n====\n';(out/(name+'.tla')).write_text(source);rows.append({'id':name,'options':control['options']})
(BASE/'selection.json').write_text(json.dumps({'schema_version':1,'selected':len(rows),'rows':rows},indent=2)+'\n')
print('Retained',len(rows),'source controls')
